mapper.select:
select  from business_audit_event
where binary domain_type=binary 'REGISTRATION' and domain_id=#{registrationId}
  and binary target_type=binary 'CMS_REGISTRATION' and target_id=#{registrationId}
  and binary action in ('REGISTRATION_STATION_REDEEM','REGISTRATION_REDEEM','GROUP_MEMBER_REDEEM','REGISTRATION_VERIFY_REVERSE')
order by id for update
